def alice_score (M : Grid) : ℕ := (Finset.univ : Finset (Fin 100)).sup (fun i => ∑ j, M i j)

noncomputable def ω : ℂ := Complex.exp (2 * Real.pi * Complex.I / 3)
def cubicPolynomial (m : ℂ) (x y z : ℂ) : ℂ := x^3 + y^3 + z^3 + m * x * y * z
noncomputable def cubeRootsOfUnity : Finset ℂ := {1, ω, ω^2}
def validMSet : Set ℂ := {-3, -3 * ω, -3 * ω^2}
def linearTrinomial (a b c : ℂ) (x y z : ℂ) : ℂ := a * x + b * y + c * z

def allPoints : List (Fin 2 × Fin 2 × Fin 2) :=
  List.product (List.ofFn id) (List.product (List.ofFn id) (List.ofFn id))
  |>.map (fun (a, (b, c)) => (a, b, c))
def gePoint (a b : Fin 2 × Fin 2 × Fin 2) : Bool :=
  a.1.val ≥ b.1.val && a.2.1.val ≥ b.2.1.val && a.2.2.val ≥ b.2.2.val
def isMonotone (f : (Fin 2 × Fin 2 × Fin 2) → Bool) : Bool :=
  allPoints.all (fun a =>
    allPoints.all (fun b =>
      if gePoint a b then
        (!f a || f b)
      else
        true
    )
  )

