  n ∈ V p ∧ n > 1 ∧
  ∀ k l : ℕ, k ∈ V p → l ∈ V p → n = k * l → k = 1 ∨ l = 1
def IsFactorization (n : ℕ) (factors : Multiset ℕ) : Prop :=
  (∀ f ∈ factors, Indecomposable p f) ∧ factors.prod = n
